<?php
require_once __DIR__.'/../../config/config.php';require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/functions.php';require_perm('stock.alerts');$db=getDB();
$rows=$db->query('SELECT i.id,i.code,i.name,i.min_stock,i.buy_price,u.abbreviation,COALESCE(SUM(s.quantity),0) total_stock,GREATEST(i.min_stock*2-COALESCE(SUM(s.quantity),0),1) suggested_qty FROM items i JOIN units u ON u.id=i.unit_id LEFT JOIN stock s ON s.item_id=i.id WHERE i.is_active=1 GROUP BY i.id,i.code,i.name,i.min_stock,i.buy_price,u.abbreviation HAVING total_stock<=i.min_stock ORDER BY total_stock,i.name')->fetch_all(MYSQLI_ASSOC);
$page_title='Peringatan Stok';include __DIR__.'/../../includes/header.php';?>
<div class="page-header d-flex justify-content-between align-items-center"><div><h4><i class="bi bi-bell me-2 text-warning"></i>Peringatan Stok</h4><p class="text-muted small mb-0">Saran pengadaan menaikkan stok ke dua kali stok minimum.</p></div><?php if($rows&&can('purchase_orders.create')):?><a href="<?=APP_URL?>/pages/purchase-orders/form.php?suggested=1" class="btn btn-primary btn-sm"><i class="bi bi-cart-plus me-1"></i>Buat PO dari Saran</a><?php endif;?></div>
<div class="card table-card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Kode</th><th>Barang</th><th class="text-end">Stok</th><th class="text-end">Minimum</th><th class="text-end">Saran Pesan</th><th class="text-end">Estimasi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="text-center text-muted py-5"><i class="bi bi-check-circle text-success fs-2"></i><br>Semua stok aman</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><code><?=e($r['code'])?></code></td><td><a href="<?=APP_URL?>/pages/items/view.php?id=<?=$r['id']?>"><?=e($r['name'])?></a></td><td class="text-end"><span class="badge <?=$r['total_stock']==0?'badge-zero':'badge-low'?>"><?=$r['total_stock']?> <?=e($r['abbreviation'])?></span></td><td class="text-end"><?=$r['min_stock']?></td><td class="text-end fw-bold"><?=$r['suggested_qty']?> <?=e($r['abbreviation'])?></td><td class="text-end"><?=idr($r['suggested_qty']*$r['buy_price'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/../../includes/footer.php';?>
